(function(root){
 'use strict';
 const amount=value=>{if(value===''||value==null)return null;const s=String(value).replaceAll(',','').trim();if(!/^\d+$/.test(s))throw Error('금액은 0 이상의 원 단위 숫자로 입력해주세요.');const n=Number(s);if(!Number.isSafeInteger(n)||n>1000000000000)throw Error('금액이 너무 큽니다. 입력값을 확인해주세요.');return n};
 function normalize(raw={}){const r={};for(const k of ['estimate','contract','deposit','interim'])r[k]=amount(raw[k]);r.mode=['separate','included','unused'].includes(raw.mode)?raw.mode:'separate';r.vendor=String(raw.vendor||'').slice(0,120);r.note=String(raw.note||'').slice(0,1000);for(const k of ['deposit','interim','balance']){r[k+'Paid']=raw[k+'Paid']===true;r[k+'Date']=/^\d{4}-\d{2}-\d{2}$/.test(raw[k+'Date']||'')?raw[k+'Date']:'';}if(r.contract===null&&(r.deposit!==null||r.interim!==null||r.balancePaid))throw Error('결제 일정을 기록하려면 계약 총액을 먼저 입력해주세요.');if((r.deposit||0)+(r.interim||0)>(r.contract||0))throw Error('예약금과 중도금 합계가 계약 총액보다 큽니다.');if(!r.deposit)r.depositPaid=false;if(!r.interim)r.interimPaid=false;return r}
 function totals(r={}){const contract=r.contract??null,balance=contract===null?null:contract-(r.deposit||0)-(r.interim||0),paid=(r.depositPaid?(r.deposit||0):0)+(r.interimPaid?(r.interim||0):0)+(r.balancePaid?(balance||0):0);return {forecast:contract??r.estimate??0,contract:contract||0,balance,paid,remaining:contract===null?0:contract-paid,known:contract!==null||r.estimate!=null};}
 function aggregate(records){return records.filter(r=>!r.mode||r.mode==='separate').reduce((s,r)=>{const t=totals(r);for(const k of ['forecast','contract','paid','remaining'])s[k]+=t[k];if(t.known)s.known++;if(r.contract==null&&r.estimate!=null)s.uncontracted++;return s},{forecast:0,contract:0,paid:0,remaining:0,known:0,uncontracted:0});}
 const api={amount,normalize,totals,aggregate};if(typeof module!=='undefined')module.exports=api;else root.BudgetCore=api;
})(typeof window!=='undefined'?window:globalThis);
